import{populateFields,clearFields}from"core_ai/helper";const Selectors={fields:{selector:'[data-modelchooser-field="selector"]',updateButton:'[data-modelchooser-field="updateButton"]',modelSettingsContainer:"id_modelsettingsheadercontainer"}};export const init=()=>{const e=document.querySelector(Selectors.fields.selector);if(e){const t=JSON.parse(e.getAttribute("data-storedmodelsettings"));const o=t[e.value];const s=Selectors.fields.modelSettingsContainer;if(o){populateFields(o,s)}else{clearFields(s)}e.addEventListener("change",t=>{e.options[t.target.selectedIndex].selected=true;const o=t.target.closest("form");const s=o.querySelector(Selectors.fields.updateButton);s.click()})}};